<script setup lang="ts">
import {ref,onMounted} from 'vue';import {request} from './api';import {money} from '../model';import PageHeader from './components/PageHeader.vue';
const overview=ref<any>({}),months=ref<any[]>([]),statuses=ref<any[]>([]),suppliers=ref<any[]>([]),busy=ref(false),error=ref('');
async function load(){busy.value=true;error.value='';try{const [a,b,c,d,e]=await Promise.all([request('/dashboard/overview'),request('/dashboard/monthly-trend'),request('/dashboard/payment-status'),request('/dashboard/top-suppliers'),request('/dictionary/options?codes=fkzt')]);overview.value=a.data;months.value=Array.from(new Set([...b.data.order_trend,...b.data.pay_trend].map((r:any)=>r.month))).sort().map(month=>({month,orders:b.data.order_trend.find((r:any)=>r.month===month)?.amount||0,payments:b.data.pay_trend.find((r:any)=>r.month===month)?.amount||0}));statuses.value=c.data.status_distribution.map((r:any)=>({...r,label:e.data.fkzt?.find((x:any)=>String(x.value)===String(r.status))?.label||r.status}));suppliers.value=d.data.top_suppliers}catch(e){error.value=(e as Error).message}finally{busy.value=false}}onMounted(load);
</script>
<template><main class="page"><PageHeader title="经营概览" description="真实业务数据与资金往来"/><van-button :loading="busy" @click="load">刷新</van-button><p v-if="error" class="m-alert error">{{error}}</p><section class="panel" v-for="(label,key) in {total_order_amount:'订单总金额',total_paid_amount:'已付款总额',pending_amount:'待付款余额'}" :key="key"><div class="m-stat"><span>{{label}}</span><strong>¥ {{money(overview[key])}}</strong></div></section><h2>月度资金趋势</h2><van-cell-group><van-cell v-for="r in months" :key="r.month" :title="r.month" :label="`订单 ¥${money(r.orders)} · 付款 ¥${money(r.payments)}`"/></van-cell-group><h2>付款状态</h2><van-cell-group><van-cell v-for="r in statuses" :key="r.status" :title="r.label" :value="`${r.count} 笔`"/></van-cell-group><h2>供应商订单排行</h2><van-cell-group><van-cell v-for="(r,i) in suppliers" :key="r.id||r.name" :title="`${i+1}. ${r.name}`" :label="`${r.order_count} 笔订单`" :value="`¥ ${money(r.total_amount)}`"/></van-cell-group></main></template>
